INSERT INTO `berita` (`id_berita`, `id_user`, `id_kategori`, `slug_berita`, `judul_berita`, `ringkasan`, `isi`, `status_berita`, `jenis_berita`, `keywords`, `gambar`, `icon`, `hits`, `tanggal_post`, `tanggal_publish`, `tanggal`) VALUES
(2, 4, 12, 'talim-masjid-al-barkah', 'Ta\'lim Masjid Al-Barkah', 'Jadwal Ta\'lim Mingguan', '<h2><strong>JADWAL TA\'LIM</strong><br /><strong>MASJID AL-BARKAH</strong></h2>\r\n<h3>Ustadz H. Abd. Syukur, S.Pd.i</h3>\r\n<ul>\r\n<li>\r\n<p><strong>Malam Rabu:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Tajwid</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Malam Jum\'at:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Hadits</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Malam Ahad:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Hadits</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Ahad Subuh:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Sifat Duapuluh</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<h3>Ustadz H. Iswadi Idris, S.H.I.</h3>\r\n<ul>\r\n<li>\r\n<p><strong>Malam Rabu:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Qomi\'ut Tughyan</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Malam Jum\'at:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Riyadul Badi\'ah</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Malam Ahad:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Bahjatul Wasaail</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Ahad Subuh:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kitab Annashoihuddiniyyah</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p><strong>Catatan:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Ta\'lim Ahad Pagi minggu pertama akan dipimpin oleh Ustadz H. Abd. Syukur S.Pd.i, dan pada minggu kedua serta seterusnya oleh Ustadz H. Iswadi Idris, S.H.I.</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3>???? <strong>Jadwal Pembaca Ratib Al-Athos (Malam Selasa) &amp; Ratib Al-Haddad (Malam Sabtu):</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Bpk. Azkar Asnawi</p>\r\n</li>\r\n<li>\r\n<p>Bpk. Ir. H. Mochsin</p>\r\n</li>\r\n<li>\r\n<p>Bpk. H. Junaedi</p>\r\n</li>\r\n<li>\r\n<p>Tedy Himawan</p>\r\n</li>\r\n<li>\r\n<p>Abd. Rosyid</p>\r\n</li>\r\n<li>\r\n<p>Habibullabiba</p>\r\n</li>\r\n<li>\r\n<p>Nurjaya</p>\r\n</li>\r\n</ul>\r\n<p>Semoga jadwal ini dapat membantu jamaah dalam mengikuti kegiatan ta\'lim yang diselenggarakan di Masjid Al-Barkah.</p>', 'Publish', 'Berita', 'Majelis Ta\'lim Al-Barkah', 'logo-masjid3.png', 'fa fa-book', 27, '2019-05-17 04:15:33', '2025-05-01 04:06:00', '2025-07-03 03:31:46'),
(3, 4, 10, 'sejarah-masjid-al-barkah', 'Sejarah Masjid Al-Barkah', 'Asal Usul dan Sejarah Berdirinya Masjid Al-Barkah', '<p><strong>Sejarah Masjid Al-Barkah</strong></p>\r\n<p>Masjid Al-Barkah merupakan salah satu masjid yang terletak di pusat kota, dengan sejarah yang kaya dan penuh makna bagi masyarakat sekitarnya. Masjid ini tidak hanya menjadi tempat ibadah, tetapi juga pusat kegiatan sosial, pendidikan, dan keagamaan bagi umat Muslim. Seiring berjalannya waktu, Masjid Al-Barkah telah menjadi simbol keberagaman dan kedamaian yang menginspirasi umat untuk selalu menjaga nilai-nilai kebersamaan dan kasih sayang.</p>\r\n<p>Masjid ini pertama kali dibangun pada tahun [Tahun Pembangunan], dengan tujuan untuk memberikan tempat ibadah yang layak bagi umat Muslim di sekitar kawasan tersebut. Pembangunannya diprakarsai oleh sekelompok masyarakat yang memiliki kepedulian tinggi terhadap pentingnya keberadaan masjid sebagai sarana penghubung antara umat dengan Allah SWT.</p>\r\n<p>Pembangunan Masjid Al-Barkah memakan waktu beberapa tahun, dengan berbagai tantangan yang dihadapi, mulai dari perencanaan, pendanaan, hingga proses pembangunan fisiknya. Namun, dengan semangat gotong royong, akhirnya masjid ini selesai dibangun dan diresmikan pada [Tanggal Peresmian], yang disaksikan oleh banyak tokoh agama dan masyarakat setempat.</p>\r\n<p>Nama \"Al-Barkah\" sendiri memiliki makna yang dalam, yang berasal dari kata \"barakah\" yang berarti keberkahan. Nama ini dipilih untuk menggambarkan harapan agar masjid ini menjadi sumber keberkahan bagi seluruh umat yang datang, baik dalam ibadah maupun dalam kehidupan sosial mereka.</p>\r\n<p>Seiring waktu, Masjid Al-Barkah terus berkembang, dengan berbagai kegiatan keagamaan dan sosial yang diadakan di dalamnya. Berbagai kajian agama, pengajian, dan acara peringatan hari besar Islam sering dilaksanakan di masjid ini. Selain itu, masjid ini juga memiliki peran penting dalam pendidikan agama bagi generasi muda melalui program pengajian anak-anak dan remaja.</p>\r\n<p>Tidak hanya menjadi tempat ibadah, Masjid Al-Barkah juga dikenal dengan aktivitas sosialnya yang melibatkan masyarakat, seperti pemberian santunan untuk anak yatim, kegiatan sosial bagi dhuafa, serta berbagai acara kemanusiaan lainnya. Semua ini dilakukan dengan tujuan untuk mempererat tali persaudaraan antar umat Islam serta memberikan manfaat bagi lingkungan sekitar.</p>\r\n<p>Masjid Al-Barkah, dengan segala sejarah dan peranannya, terus menjadi pusat spiritual yang memberikan ketenangan dan keberkahan bagi umat Muslim. Hingga kini, masjid ini tetap menjadi tempat yang penuh makna dan memberikan kontribusi yang besar terhadap perkembangan masyarakat setempat.</p>\r\n<p>Dengan segala aktivitas dan kebaikan yang terus dilakukan, Masjid Al-Barkah tetap menjadi tempat yang dihormati dan disegani, sebagai simbol dari semangat kebersamaan dan keberkahan dalam hidup beragama.</p>', 'Publish', 'Profil', '', 'logo-masjid2.jpg', 'fa fa-mosque', 49, '2019-05-17 04:37:00', '2019-05-17 04:36:00', '2025-07-24 07:37:17'),
(4, 4, 11, 'struktur-dkm', 'Struktur DKM', 'Struktur DKM Masjid Al-Barkah, dan Koordinatornya.', '<p data-start=\"268\" data-end=\"294\"><strong data-start=\"268\" data-end=\"294\">1. Penasehat / Pembina</strong></p>\r\n<ul data-start=\"295\" data-end=\"415\">\r\n<li data-start=\"295\" data-end=\"347\">\r\n<p data-start=\"297\" data-end=\"347\">Tokoh agama, tokoh masyarakat, atau pejabat lokal.</p>\r\n</li>\r\n<li data-start=\"348\" data-end=\"415\">\r\n<p data-start=\"350\" data-end=\"415\">Fungsi: memberikan arahan umum dan nasihat terhadap kegiatan DKM.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"417\" data-end=\"438\"><strong data-start=\"417\" data-end=\"438\">2. Ketua Umum DKM</strong></p>\r\n<ul data-start=\"439\" data-end=\"504\">\r\n<li data-start=\"439\" data-end=\"504\">\r\n<p data-start=\"441\" data-end=\"504\">Bertanggung jawab atas seluruh kegiatan dan pengelolaan masjid.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"506\" data-end=\"524\"><strong data-start=\"506\" data-end=\"524\">3. Wakil Ketua</strong></p>\r\n<ul data-start=\"525\" data-end=\"600\">\r\n<li data-start=\"525\" data-end=\"600\">\r\n<p data-start=\"527\" data-end=\"600\">Membantu ketua dalam pelaksanaan tugas dan menggantikan bila berhalangan.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"602\" data-end=\"619\"><strong data-start=\"602\" data-end=\"619\">4. Sekretaris</strong></p>\r\n<ul data-start=\"620\" data-end=\"693\">\r\n<li data-start=\"620\" data-end=\"664\">\r\n<p data-start=\"622\" data-end=\"664\">Mengelola administrasi dan surat menyurat.</p>\r\n</li>\r\n<li data-start=\"665\" data-end=\"693\">\r\n<p data-start=\"667\" data-end=\"693\">Menyusun laporan kegiatan.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"695\" data-end=\"711\"><strong data-start=\"695\" data-end=\"711\">5. Bendahara</strong></p>\r\n<ul data-start=\"712\" data-end=\"810\">\r\n<li data-start=\"712\" data-end=\"768\">\r\n<p data-start=\"714\" data-end=\"768\">Mengelola keuangan masjid (pemasukan dan pengeluaran).</p>\r\n</li>\r\n<li data-start=\"769\" data-end=\"810\">\r\n<p data-start=\"771\" data-end=\"810\">Menyusun laporan keuangan secara rutin.</p>\r\n</li>\r\n</ul>', 'Publish', 'Profil', '', 'Desain-tanpa-judul.png', 'fa fa-users', 15, '2019-07-26 10:38:15', '2019-07-26 10:36:00', '2025-07-03 03:31:01'),
(6, 4, 13, 'peringatan-maulid-nabi-muhammad-saw', 'Peringatan Maulid Nabi Muhammad SAW', '', '<p class=\"\" data-start=\"128\" data-end=\"187\"><strong data-start=\"128\" data-end=\"187\">Peringatan Maulid Nabi Muhammad SAW di Masjid Al-Barkah</strong></p>\r\n<p class=\"\" data-start=\"189\" data-end=\"405\">Mari kita bersama-sama memperingati kelahiran Nabi Muhammad SAW dengan penuh kebahagiaan dan keberkahan di <strong data-start=\"296\" data-end=\"316\">Masjid Al-Barkah</strong>. Acara ini akan menjadi momen istimewa yang penuh dengan doa, ilmu, dan ketenangan hati.</p>\r\n<p class=\"\" data-start=\"407\" data-end=\"530\"><strong data-start=\"407\" data-end=\"426\">Hari/Tanggal</strong>: Jum\'at, 27 September 2024<br data-start=\"463\" data-end=\"466\" /><strong data-start=\"466\" data-end=\"478\">Waktu</strong>: 19.30 s/d Selesai<br data-start=\"496\" data-end=\"499\" /><strong data-start=\"499\" data-end=\"512\">Tempat</strong>: Jl. H. Salim RT 009/06 Kel. Bintaro</p>\r\n<p class=\"\" data-start=\"532\" data-end=\"727\"><strong data-start=\"532\" data-end=\"546\">Penceramah</strong>:<br data-start=\"547\" data-end=\"550\" /><strong data-start=\"552\" data-end=\"565\">Ustadz H. M. Syarifudin, S.Pd.I</strong>, yang akan menyampaikan tausiyah penuh hikmah tentang kehidupan dan perjuangan Nabi Muhammad SAW, serta teladan yang bisa kita ambil untuk kehidupan sehari-hari.</p>\r\n<p class=\"\" data-start=\"729\" data-end=\"857\"><strong data-start=\"729\" data-end=\"737\">Qori</strong>:<br data-start=\"738\" data-end=\"741\" /><strong data-start=\"744\" data-end=\"769\">Ustadz H. Abdul Mufarrich, M.Pd</strong>, yang akan memukau kita dengan lantunan ayat-ayat suci Al-Qur\'an yang menyejukkan jiwa.</p>\r\n<p class=\"\" data-start=\"859\" data-end=\"1115\">Jangan lewatkan kesempatan untuk mendapatkan keberkahan dari acara ini. Ajak keluarga, sahabat, dan tetangga untuk hadir dan menyambut momen penuh berkah ini bersama-sama. Semoga kita semua semakin dekat dengan Rasulullah SAW dan memperoleh syafa\'at-Nya.</p>\r\n<p class=\"\" data-start=\"1117\" data-end=\"1225\"><strong data-start=\"1117\" data-end=\"1224\">Bersama, mari kita mempererat tali silaturahmi dan memperdalam kecintaan kita kepada Nabi Muhammad SAW.</strong></p>', 'Publish', 'Berita', 'Peringatan Maulid Nabi Muhammad SAW', 'IMG-20240914-WA0001[1].jpg', 'fa fa-book', 23, '2020-02-13 07:42:56', '2020-02-13 07:41:00', '2025-09-23 05:26:09'),
(22, 4, 13, 'penyembelihan-hewan-qurban', 'Penyembelihan Hewan Qurban', '', '<p data-start=\"81\" data-end=\"344\">Assalamu&rsquo;alaikum warahmatullahi wabarakatuh,<br data-start=\"125\" data-end=\"128\" />Dengan penuh rasa syukur dan semangat kebersamaan dalam merayakan Idul Adha 1446 H, kami mengundang Bapak/Ibu/Saudara/i untuk <strong data-start=\"254\" data-end=\"304\">menyaksikan prosesi penyembelihan hewan qurban</strong> yang insyaAllah akan dilaksanakan pada:</p>\r\n<p data-start=\"346\" data-end=\"494\">???? <strong data-start=\"349\" data-end=\"359\">Tempat</strong>: Lapangan Masjid Al Barkah<br data-start=\"377\" data-end=\"380\" />???? <strong data-start=\"383\" data-end=\"399\">Hari/Tanggal</strong>: Sabtu, 7 Juni 2025<br data-start=\"429\" data-end=\"432\" />? <strong data-start=\"434\" data-end=\"443\">Waktu</strong>: Pukul 08.00 - Selesai</p>\r\n<p data-start=\"496\" data-end=\"624\">Mari bersama-sama menyaksikan dan mengambil hikmah dari pelaksanaan ibadah qurban sebagai bentuk ketaatan dan kepedulian sosial.</p>\r\n<p data-start=\"626\" data-end=\"732\"><strong data-start=\"626\" data-end=\"637\">Catatan</strong>:<br data-start=\"638\" data-end=\"641\" />Diharapkan untuk hadir dengan tetap menjaga kebersihan dan ketertiban di lingkungan masjid.</p>\r\n<p data-start=\"734\" data-end=\"779\">Wassalamu&rsquo;alaikum warahmatullahi wabarakatuh.</p>\r\n<p data-start=\"781\" data-end=\"828\">Panitia Idul Adha 1446 H<br data-start=\"805\" data-end=\"808\" /><strong data-start=\"808\" data-end=\"828\">Masjid Al Barkah</strong></p>', 'Publish', 'Berita', 'Hewan Qurban', 'Masjid-Al-Barkah-(1080-x-1080-piksel)-(2).png', '', 14, '2021-04-24 08:05:28', '1970-01-01 17:24:00', '2025-07-15 07:26:47'),
(24, 4, 3, 'santunan-anak-yatim', 'Santunan Anak Yatim', '', '<p class=\"\" data-start=\"123\" data-end=\"171\"><strong data-start=\"123\" data-end=\"171\">Assalamu\'alaikum Warahmatullahi Wabarakatuh,</strong></p>\r\n<p class=\"\" data-start=\"173\" data-end=\"371\">Mari sambut Tahun Baru Islam 1446 H dengan berbagi kepada sesama. Masjid Al Barkah membuka kesempatan bagi Anda untuk berdonasi kepada anak yatim dan dhuafa melalui paket bantuan yang kami sediakan.</p>\r\n<p class=\"\" data-start=\"373\" data-end=\"390\"><strong data-start=\"373\" data-end=\"390\">Paket Donasi:</strong></p>\r\n<ol data-start=\"391\" data-end=\"459\">\r\n<li class=\"\" data-start=\"391\" data-end=\"423\">\r\n<p class=\"\" data-start=\"394\" data-end=\"423\"><strong data-start=\"394\" data-end=\"409\">Paket Uang:</strong> Rp. 200.000,-</p>\r\n</li>\r\n<li class=\"\" data-start=\"424\" data-end=\"459\">\r\n<p class=\"\" data-start=\"427\" data-end=\"459\"><strong data-start=\"427\" data-end=\"445\">Paket Sembako:</strong> Rp. 200.000,-</p>\r\n</li>\r\n</ol>\r\n<p class=\"\" data-start=\"461\" data-end=\"496\"><strong data-start=\"461\" data-end=\"496\">Donasi dapat dilakukan melalui:</strong></p>\r\n<ul data-start=\"497\" data-end=\"575\">\r\n<li class=\"\" data-start=\"497\" data-end=\"575\">\r\n<p class=\"\" data-start=\"499\" data-end=\"575\"><strong data-start=\"499\" data-end=\"520\">Rekening Bank DKI</strong><br data-start=\"520\" data-end=\"523\" />No. Rekening: 72021001587<br data-start=\"550\" data-end=\"553\" />a.n Masjid Al Barkah</p>\r\n</li>\r\n</ul>\r\n<p class=\"\" data-start=\"577\" data-end=\"626\"><strong data-start=\"577\" data-end=\"626\">Informasi lebih lanjut dan konfirmasi donasi:</strong></p>\r\n<ul data-start=\"627\" data-end=\"668\">\r\n<li class=\"\" data-start=\"627\" data-end=\"668\">\r\n<p class=\"\" data-start=\"629\" data-end=\"668\"><strong data-start=\"629\" data-end=\"636\">WA:</strong> 0812 1151 4356 / 0857 7261 3790</p>\r\n</li>\r\n</ul>\r\n<p class=\"\" data-start=\"670\" data-end=\"798\">Mari berikan sedikit rezeki kita untuk meringankan beban mereka. Setiap donasi Anda sangat berarti bagi mereka yang membutuhkan.</p>\r\n<p class=\"\" data-start=\"800\" data-end=\"905\">Semoga Allah SWT membalas setiap kebaikan dengan pahala yang berlipat ganda.<br data-start=\"876\" data-end=\"879\" /><strong data-start=\"879\" data-end=\"905\">Jazakumullahu Khairan.</strong></p>\r\n<p class=\"\" data-start=\"907\" data-end=\"975\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.<br data-start=\"952\" data-end=\"955\" /><strong data-start=\"955\" data-end=\"975\">Masjid Al Barkah</strong></p>', 'Draft', 'Layanan', 'Santunan Anak Yatim', 'IMG-20250501-WA0014[1].jpg', 'fa fa-book', 31, '2021-04-24 12:06:07', '2024-07-16 00:00:00', '2025-05-25 05:28:46'),
(26, 4, 11, 'program-kegiatan-masjid', 'Program Kegiatan Masjid', 'DKM Masjid Al-Barkah Membuat Program dan Kegiatan Seperti Kajian Mingguan, Bulanan, Dll. ', '<ul>\r\n<li data-start=\"142\" data-end=\"306\">\r\n<p data-start=\"144\" data-end=\"306\"><strong data-start=\"144\" data-end=\"164\">Shalat Berjamaah</strong><br data-start=\"164\" data-end=\"167\" />Menyelenggarakan shalat lima waktu, shalat Jumat, shalat Tarawih selama Ramadhan, serta shalat Idul Fitri dan Idul Adha secara berjamaah.</p>\r\n</li>\r\n<li data-start=\"308\" data-end=\"476\">\r\n<p data-start=\"310\" data-end=\"476\"><strong data-start=\"310\" data-end=\"331\">Kajian Islam Umum</strong><br data-start=\"331\" data-end=\"334\" />Kajian rutin mingguan atau bulanan yang membahas tafsir Al-Qur&rsquo;an, fiqih, hadits, akhlak, dan tema-tema keislaman lainnya untuk jamaah umum.</p>\r\n</li>\r\n<li data-start=\"478\" data-end=\"635\">\r\n<p data-start=\"480\" data-end=\"635\"><strong data-start=\"480\" data-end=\"518\">Peringatan Hari Besar Islam (PHBI)</strong><br data-start=\"518\" data-end=\"521\" />Mengadakan kegiatan peringatan Maulid Nabi, Isra Mi&rsquo;raj, Tahun Baru Hijriyah, dll.</p>\r\n</li>\r\n</ul>', 'Publish', 'Profil', '', 'Desain-tanpa-judul.png', ' fa fa-list', 15, '2025-04-30 10:41:35', '2025-04-30 10:40:00', '2025-09-23 05:27:26');
INSERT INTO `donasi` (`id_donasi`, `judul_donasi`, `slug_donasi`, `deskripsi_singkat`, `deskripsi_lengkap`, `gambar`, `target_donasi`, `jumlah_terkumpul`, `tanggal_mulai`, `tanggal_selesai`, `STATUS`, `lembaga`, `kategori`, `created_at`, `updated_at`) VALUES
(1, 'Sedekah Yatim dan Dhuafa', 'sedekah-yatim-dhuafa', 'Mari bantu anak yatim dan dhuafa melalui sedekah terbaik Anda.', 'Program Sedekah Yatim dan Dhuafa ini bertujuan membantu memenuhi kebutuhan harian, pendidikan, serta kesejahteraan anak-anak yatim dan keluarga dhuafa. Dana akan disalurkan secara langsung oleh tim BAZNAS bekerja sama dengan Masjid Al Barkah.', '1751512959_602d7af4672d34569162.png', 5000000000, 106000000, '2025-05-15', '2025-11-23', 'Publish', 'Masjid Al Barkah', 'Yatim & Dhuafa', '2025-05-23 10:54:01', '2025-07-03 10:22:39'),
(9, 'Wakaf Al-Qur’an untuk Santri Pelosok', 'wakaf-quran-santri-pelosok', 'Tebar cahaya Al-Qur’an ke pelosok negeri', 'Banyak pesantren dan madrasah di pelosok nusantara masih kekurangan mushaf Al-Qur’an yang layak. Program ini bertujuan mendistribusikan wakaf mushaf ke daerah-daerah pelosok, terutama untuk santri dhuafa.', '1751512997_2fdd13053fc03a1194d9.png', 20000000, 5000000, '2025-05-09', '2025-10-23', 'Publish', 'Masjid Al Barkah', 'Wakaf & Pendidikan', '2025-05-25 12:24:29', '2025-07-03 10:23:17'),
(10, 'Donasi Pembangunan Masjid Al-Barkah', 'donasi-pembangunan-masjid-albarkah', 'Bantu pembangunan Masjid Al-Barkah untuk kenyamanan ibadah dan kegiatan umat.', 'Masjid Al-Barkah saat ini sedang dalam tahap pembangunan untuk menjadi pusat ibadah yang nyaman, aman, dan representatif bagi masyarakat sekitar. Kami mengajak Bapak/Ibu serta seluruh kaum muslimin untuk ikut serta dalam amal jariyah ini melalui donasi seikhlasnya. Dana yang terkumpul akan digunakan untuk pembangunan ruang utama, tempat wudhu, fasilitas kebersihan, serta sarana pendukung lainnya. Semoga setiap rupiah yang disumbangkan menjadi pahala yang terus mengalir. Aamiin.', '1751513023_05e54651908380a8f58a.png', 200000000, 3000000, '2025-06-10', '2026-11-30', 'Publish', 'Masjid Al Barkah', 'Pembangunan Masjid', '2025-06-10 14:28:57', '2025-07-03 10:23:43');
