INSERT INTO `konfigurasi` (`id_konfigurasi`, `id_user`, `namaweb`, `singkatan`, `tagline`, `tentang`, `deskripsi`, `website`, `email`, `email_cadangan`, `alamat`, `telepon`, `hp`, `logo`, `icon`, `keywords`, `metatext`, `facebook`, `twitter`, `instagram`, `youtube`, `nama_facebook`, `nama_twitter`, `nama_instagram`, `nama_youtube`, `google_map`, `protocol`, `smtp_host`, `smtp_port`, `smtp_timeout`, `smtp_user`, `smtp_pass`, `tanggal`) VALUES
(1, 4, 'Masjid Al-Barkah', 'MALB', 'Keberkahan dalam Setiap Langkah, Kedamaian dalam Setiap Doa', '<p class=\"\" data-start=\"102\" data-end=\"509\"><strong>Masjid Al-Barkah</strong> adalah rumah ibadah yang terletak di jantung kota, dibangun dengan tujuan untuk memberikan tempat yang nyaman dan tenang bagi umat Islam untuk menjalankan ibadah, berdoa, dan berkumpul. Dikenal dengan arsitektur yang megah dan nuansa yang damai, Masjid Al-Barkah tidak hanya berfungsi sebagai tempat shalat, tetapi juga sebagai pusat kegiatan sosial dan pendidikan untuk masyarakat sekitar.</p>\r\n<p class=\"\" data-start=\"511\" data-end=\"838\">Masjid ini memiliki berbagai fasilitas yang mendukung kegiatan keagamaan dan sosial, seperti ruang pengajian, ruang pertemuan, dan area parkir yang luas. Selain itu, Masjid Al-Barkah juga aktif mengadakan berbagai kegiatan keagamaan, seperti pengajian rutin, kajian ilmu agama, dan acara sosial yang melibatkan komunitas lokal.</p>\r\n<p class=\"\" data-start=\"840\" data-end=\"1203\">Dengan visi untuk menjadi pusat keberkahan bagi umat Islam, Masjid Al-Barkah terus berkomitmen untuk memberikan kontribusi positif kepada masyarakat dan lingkungan sekitarnya. Kami berharap Masjid Al-Barkah dapat menjadi tempat yang tidak hanya memberikan kedamaian bagi jamaah, tetapi juga memberikan inspirasi untuk menjalani kehidupan yang penuh dengan berkah.</p>', 'Masjid Al-Barkah adalah rumah ibadah yang nyaman dengan arsitektur megah, aktif dalam kegiatan keagamaan dan sosial. Berkomitmen menjadi pusat keberkahan bagi masyarakat sekitar.', 'Jl. H. Minun No.18, RT.9/RW.6, Bintaro', 'masjidalbarkah@gmail.com', 'masjidalbarkah12@gmail.com', '<p><b>MASJID AL-BARKAH</b><br>Jl. H. Minun No.18, RT.9/RW.6, Bintaro, Kec. Pesanggrahan, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12330<br></p>', '+628881150984', '+6281211514356', 'logo masjid3.png', 'ChatGPT Image Apr 30, 2025, 06_21_47 AM (2).png', 'Java Web Media adalah Pusat Kursus Private dan Reguler bidang Desain Grafis, Web Programming, Mobile Application dan Statistik\r\n', 'adada', 'https://www.facebook.com/', 'http://twitter.com/', 'https://instagram.com/', 'https://www.youtube.com/', 'Masjid Al-Barkah', 'Masjid Al-Barkah', 'Masjid Al-Barkah', 'Masjid Al-Barkah', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d589.5441131281301!2d106.75926176196691!3d-6.268432085580011!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f05aa121d28f%3A0x130dafdfb61cdf6c!2sMasjid%20Al%20Barkah!5e0!3m2!1sen!2sid!4v1745999884673!5m2!1sen!2sid\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', 'smtp', 'ssl://mail.websitemu.com', 465, 7, 'contact@websitemu.com', 'muhammad', '2025-05-01 07:33:52');
